create extension if not exists pgcrypto;
create table if not exists public.species_taxa(id uuid primary key default gen_random_uuid(),scientific_name text not null unique,common_name_es text,common_name_en text,family text,taxon_source text not null,taxon_source_url text,taxon_source_checked_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists public.observations(id uuid primary key default gen_random_uuid(),observer_id uuid references auth.users(id) on delete set null,species_id uuid references public.species_taxa(id) on delete set null,suggested_scientific_name text,observed_at timestamptz not null,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),positional_accuracy_m numeric,notes text,habitat_type text,host_plant text,nectar_plant text,verification_status text not null default 'submitted' check(verification_status in('submitted','needs_review','verified','rejected')),verification_confidence numeric check(verification_confidence is null or verification_confidence between 0 and 1),verifier_id uuid references auth.users(id) on delete set null,verified_at timestamptz,source_type text not null default 'citizen' check(source_type in('citizen','research','government','import')),source_reference text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.observation_media(id uuid primary key default gen_random_uuid(),observation_id uuid not null references public.observations(id) on delete cascade,storage_path text not null,media_type text not null default 'photo' check(media_type in('photo','audio','video')),license text,created_at timestamptz not null default now());
create table if not exists public.habitat_incidents(id uuid primary key default gen_random_uuid(),reporter_id uuid references auth.users(id) on delete set null,incident_type text not null check(incident_type in('pesticide','vegetation_removal','fire','pollution','construction','water_stress','other')),observed_at timestamptz not null,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),description text not null,verification_status text not null default 'submitted' check(verification_status in('submitted','needs_review','verified','rejected')),created_at timestamptz not null default now());
create index if not exists observations_species_date_idx on public.observations(species_id,observed_at desc);create index if not exists observations_status_date_idx on public.observations(verification_status,observed_at desc);create index if not exists habitat_incidents_status_date_idx on public.habitat_incidents(verification_status,observed_at desc);
alter table public.species_taxa enable row level security;alter table public.observations enable row level security;alter table public.observation_media enable row level security;alter table public.habitat_incidents enable row level security;
create policy "public reads taxonomy" on public.species_taxa for select using(true);
create policy "public reads verified observations" on public.observations for select using(verification_status='verified');
create policy "authenticated creates observations" on public.observations for insert to authenticated with check(observer_id=auth.uid());
create policy "owners read own observations" on public.observations for select to authenticated using(observer_id=auth.uid() or verification_status='verified');
create policy "owners update submitted observations" on public.observations for update to authenticated using(observer_id=auth.uid() and verification_status in('submitted','needs_review')) with check(observer_id=auth.uid());
create policy "owners manage observation media" on public.observation_media for all to authenticated using(exists(select 1 from public.observations o where o.id=observation_id and o.observer_id=auth.uid())) with check(exists(select 1 from public.observations o where o.id=observation_id and o.observer_id=auth.uid()));
create policy "public reads verified incidents" on public.habitat_incidents for select using(verification_status='verified');
create policy "authenticated creates incidents" on public.habitat_incidents for insert to authenticated with check(reporter_id=auth.uid());
